import{_ as t,o,c as a,a2 as d}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"유니티 구조","description":"","frontmatter":{},"headers":[],"relativePath":"rules/Unity-Architecture.md","filePath":"rules/Unity-Architecture.md"}'),i={name:"rules/Unity-Architecture.md"};function n(c,e,r,l,s,h){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="유니티-구조" tabindex="-1">유니티 구조 <a class="header-anchor" href="#유니티-구조" aria-label="Permalink to &quot;유니티 구조&quot;">​</a></h1><p><img src="https://github.com/islee23520/seoul-kenshi/blob/main/docs/assets/wiki/isometric-grammar.svg?raw=true" alt="유니티 화면에서 칸에 누가 서 있고 어느 쪽을 보며 어디까지 보이는지"></p><h2 id="기준선" tabindex="-1">기준선 <a class="header-anchor" href="#기준선" aria-label="Permalink to &quot;기준선&quot;">​</a></h2><p>현재 기반은 Unity <code>6000.7.0a5</code>입니다. 시험판이므로 편집기 판본과 패키지 잠금 파일을 함께 고정하고, 판본을 올리기 전에 따로 검증합니다.</p><p>현재 구현된 기반은 다음입니다.</p><ul><li>Unity <code>6000.7.0a5</code> 프로젝트</li><li>장르 계약 JSON과 상수, EditMode 장르 계약 테스트</li><li>URP, Input System, Test Framework, VContainer <code>1.19.0</code></li><li><code>Bootstrap.unity</code> App scope와 FSM, <code>Foundation.unity</code> 화면 child scope</li><li>단일 scene-load 권한과 정적 아키텍처 게이트</li></ul><p>이 기반 위에 <code>Unity POC 통합 코어 루프</code>가 실렸습니다. <code>MainTitle</code> 화면 lease, 세 역 노선, 교섭·우회, 30Hz 실시간 진형·카드 전투(<code>rtfc-owner-cards-v2</code>), 정확히 한 번 정산, uGUI HUD가 <code>Janseon.Core</code>와 <code>Janseon.Foundation</code>에 있습니다. 화면은 <a href="/design/Ui-Implementation-Pipeline.html">UI가 코드로 들어오는 길</a>을 따릅니다. HTML 목업을 동결한 뒤에 uGUI로 옮기고, 클릭 대상은 목업과 같은 그림입니다. 생성 아트 슬롯·16국 캠페인·집계 사상자 표현은 아직 완료가 아닙니다.</p><h2 id="영역별-책임" tabindex="-1">영역별 책임 <a class="header-anchor" href="#영역별-책임" aria-label="Permalink to &quot;영역별 책임&quot;">​</a></h2><p>현재 저장소 어셈블리는 <code>Janseon.Core</code>(엔진 금지), <code>Janseon.Foundation</code>, <code>Janseon.Data</code>, <code>Janseon.Art</code>입니다. 전투 계약과 시뮬레이션은 Core 안의 <code>Battle.Contracts</code>·<code>Battle.Sim</code> 네임스페이스이고, 별도 <code>Janseon.Battle</code> 어셈블리는 없습니다.</p><table tabindex="0"><thead><tr><th>모듈</th><th>책임</th><th>UnityEngine 참조</th></tr></thead><tbody><tr><td><code>Janseon.Core</code></td><td>ID, 시간, 명령, 사건, 노선, 캠페인, 정산, 실시간 진형·카드 전투</td><td>금지</td></tr><tr><td><code>Janseon.Data</code></td><td>Unity 저작 데이터</td><td>허용</td></tr><tr><td><code>Janseon.Foundation</code></td><td>씬 흐름, 화면, uGUI, 전투 드라이버</td><td>허용</td></tr><tr><td><code>Janseon.Art</code></td><td>런타임 슬롯·후보</td><td>허용</td></tr></tbody></table><h2 id="규칙" tabindex="-1">규칙 <a class="header-anchor" href="#규칙" aria-label="Permalink to &quot;규칙&quot;">​</a></h2><ul><li>엔진 독립 모듈에는 전역 가변 상태를 두지 않습니다.</li><li>화면은 상태를 직접 수정하지 않고 명령을 보냅니다.</li><li>모든 상태 변화는 사건 원장에 기록합니다.</li><li>고급 패키지는 실제 사용처와 실패 테스트가 생긴 뒤 추가합니다.</li></ul>',12)])])}const m=t(i,[["render",n]]);export{p as __pageData,m as default};
